1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  /** Zero-based index of the quote step that created the policy. */
30	  policy: number;
31	  incident: Incident;
32	}
33	
34	export type Step = QuoteStep | ClaimStep;
35	
36	export interface Scenario {
37	  customer: Customer;
38	  steps: Step[];
39	}
40	
41	export interface QuoteResult {
42	  premium: number;
43	}
44	
45	export interface ClaimResult {
46	  payout: number;
47	  remainingCap: number;
48	}
49	
50	export type StepResult = QuoteResult | ClaimResult;
51	
52	export interface ScenarioResults {
53	  results: StepResult[];
54	}
