56	/**
57	 * A customer as they stand at one point in a scenario: who they are, plus what
58	 * they have already been quoted. `quotesSoFar` counts *quotes priced*, not
59	 * steps taken — once claim steps exist the two will differ, and it is the quote
60	 * count that decides whether a policy is a follow-up contract.
61	 */
62	interface CustomerStanding {
63	  readonly customer: Customer;
64	  readonly quotesSoFar: number;
65	}
66	
67	const PROCESSING_FEE = 5;
68	
69	/**
70	 * The spec keeps intermediate amounts as exact fractions and rounds only the
71	 * final amount. Binary floating point cannot do that: `100 * 1.1` is
72	 * 110.00000000000001, which rounds *up* to 111 instead of 110.
73	 *
74	 * So percentages are applied as integer rationals — multiply by the numerator
75	 * first, divide by the denominator last — and money is carried in hundredths
76	 * of a G. Both operands of every product stay integral, so no drift accrues.
77	 */
78	const SUBUNITS_PER_G = 100;
79	const toSubunits = (gold: number): number => Math.round(gold * SUBUNITS_PER_G);
80	
81	/**
82	 * A percentage held as an exact rational, so that it can be applied without
83	 * float drift: multiply by `num` first, divide by `den` last.
84	 *
85	 * Deliberately anonymous about *meaning*. Both sides of the business use
86	 * percentages, but they use them for opposite things — see `Rate` and `Share`,
87	 * which are the names the domain actually reads in.
88	 */
89	interface Fraction {
90	  num: number;
91	  den: number;
92	}
93	
94	/** The part of `subunits` that `fraction` denotes. */
95	const partOf = (subunits: number, fraction: Fraction): number =>
96	  (subunits * fraction.num) / fraction.den;
97	
98	/**
99	 * A modifier as an exact rational: the surcharge or discount *itself*, not the
100	 * multiplied total. +10 % is { num: 10, den: 100 }; a discount has a negative
101	 * numerator. Modifiers are summed onto a base, never multiplied through it.
102	 */
103	type Rate = Fraction;
104	
105	const FIRST_INSURANCE_SURCHARGE: Rate = { num: 10, den: 100 };
106	const CURSE_SURCHARGE: Rate = { num: 50, den: 100 };
107	const HIGH_ENCHANTMENT_SURCHARGE: Rate = { num: 30, den: 100 };
108	
109	const LOYALTY_DISCOUNT: Rate = { num: -20, den: 100 };
110	const FOLLOW_UP_DISCOUNT: Rate = { num: -15, den: 100 };
111	
112	/** An item is highly enchanted from this level upwards. */
113	const HIGH_ENCHANTMENT_LEVEL = 5;
114	
115	/** A customer is long-standing from this many years of business upwards. */
116	const LOYALTY_YEARS = 2;
117	
118	/** The modifier amount `rate` contributes against `subunits` — not the total. */
119	const rateAmount = (subunits: number, rate: Rate): number => partOf(subunits, rate);
120	
121	/** Premiums round up — in the MHPCO's favour. */
122	const toPremiumGold = (subunits: number): number => Math.ceil(subunits / SUBUNITS_PER_G);
123	
124	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
125	  sword: 100,
126	  amulet: 60,
127	  staff: 80,
128	  potion: 40,
129	  rune: 25,
130	  moonstone: 25,
131	};
132	
133	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_ITEM_TYPE[item.type] ?? 0;
134	
135	/** What an item is insured for — distinct from what it costs to insure. */
136	const INSURANCE_VALUE_BY_ITEM_TYPE: Record<string, number> = {
137	  sword: 1000,
138	  amulet: 600,
139	  staff: 800,
140	  potion: 400,
141	  rune: 250,
142	  moonstone: 250,
143	};
144	
145	const insuranceValueOf = (item: Item): number => INSURANCE_VALUE_BY_ITEM_TYPE[item.type] ?? 0;
146	
147	const COMPONENT_TYPES = ["rune", "moonstone"];
148	
149	const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);
150	
151	/** Exactly this many alike components form a block, priced as one unit. */
152	const COMPONENT_BLOCK_SIZE = 3;
153	const COMPONENT_BLOCK_PREMIUM = 60;
154	
155	/** Splits items into those matching the predicate and those that do not. */
156	const partition = (items: Item[], matches: (item: Item) => boolean): [Item[], Item[]] => [
157	  items.filter(matches),
158	  items.filter((item) => !matches(item)),
159	];
160	
161	const groupByType = (items: Item[]): Map<string, Item[]> => {
162	  const groups = new Map<string, Item[]>();
163	  for (const item of items) groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
164	
165	  return groups;
166	};
167	
168	const sumOfBasePremiums = (items: Item[]): number =>
169	  items.reduce((total, item) => total + basePremiumOf(item), 0);
170	
171	/**
172	 * Alike components — those of the very same type — form a block when there are
173	 * exactly COMPONENT_BLOCK_SIZE of them; the block is priced as one unit.
174	 * Any other count is priced per component.
175	 */
176	const componentGroupPremium = (group: Item[]): number =>
177	  group.length === COMPONENT_BLOCK_SIZE ? COMPONENT_BLOCK_PREMIUM : sumOfBasePremiums(group);
178	
179	/**
180	 * The policy base premium: every insured item's base premium, summed — except
181	 * that each group of alike components is priced as blocks where it can be.
182	 */
183	const policyBasePremiumOf = (items: Item[]): number => {
184	  const [components, mainItems] = partition(items, isComponent);
185	  const componentsTotal = [...groupByType(components).values()].reduce(
186	    (total, group) => total + componentGroupPremium(group),
187	    0,
188	  );
189	
190	  return sumOfBasePremiums(mainItems) + componentsTotal;
191	};
192	
193	/** The total the given rates contribute against a shared base. */
194	const sumOfRateAmounts = (base: number, rates: Rate[]): number =>
195	  rates.reduce((total, rate) => total + rateAmount(base, rate), 0);
196	
197	const isHighlyEnchanted = (item: Item): boolean =>
198	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
199	
200	/** Which item-specific modifiers an item attracts, by its own attributes. */
201	const ratesForItem = (item: Item): Rate[] => [
202	  ...(item.cursed ? [CURSE_SURCHARGE] : []),
203	  ...(isHighlyEnchanted(item) ? [HIGH_ENCHANTMENT_SURCHARGE] : []),
204	];
205	
206	const isLongStanding = (standing: CustomerStanding): boolean =>
207	  standing.customer.yearsWithMHPCO >= LOYALTY_YEARS;
208	
209	const holdsAnEarlierQuote = (standing: CustomerStanding): boolean => standing.quotesSoFar > 0;
210	
211	/** Which policy-wide modifiers a policy attracts, by the customer's standing. */
212	const ratesForPolicy = (standing: CustomerStanding): Rate[] => [
213	  FIRST_INSURANCE_SURCHARGE,
214	  ...(isLongStanding(standing) ? [LOYALTY_DISCOUNT] : []),
215	  ...(holdsAnEarlierQuote(standing) ? [FOLLOW_UP_DISCOUNT] : []),
216	];
217	
218	/** Item-specific modifiers apply to the affected item's own base premium. */
219	const sumOfItemModifierAmounts = (items: Item[]): number =>
220	  items.reduce(
221	    (total, item) =>
222	      total + sumOfRateAmounts(toSubunits(basePremiumOf(item)), ratesForItem(item)),
223	    0,
224	  );
225	
226	/**
227	 * Modifiers are additive amounts, each computed against its own base: item
228	 * modifiers against the affected item, policy-wide modifiers against the
229	 * policy base premium. The processing fee is added at the very end.
230	 */
231	const quotePremium = (items: Item[], standing: CustomerStanding): number => {
232	  const policyBase = toSubunits(policyBasePremiumOf(items));
233	
234	  return toPremiumGold(
235	    policyBase +
236	      sumOfItemModifierAmounts(items) +
237	      sumOfRateAmounts(policyBase, ratesForPolicy(standing)) +
238	      toSubunits(PROCESSING_FEE),
239	  );
240	};
241	
242	/** A deductible is withheld from each damaged item's reimbursement. */
243	const DEDUCTIBLE = 100;
244	
245	/** The MHPCO pays at most this multiple of a policy's insurance sum. */
246	const CAP_MULTIPLE = 2;
247	
248	/** Payouts round down — in the MHPCO's favour. */
249	const toPayoutGold = (subunits: number): number => Math.floor(subunits / SUBUNITS_PER_G);
250	
251	/**
252	 * A policy created by a quote step: the items it covers, and how much of its
253	 * payout cap is still available.
254	 */
255	interface Policy {
256	  readonly items: Item[];
257	  readonly remainingCap: number;
258	}
259	
260	/**
261	 * What a policy insures for in total: every covered item's own insurance value,
262	 * summed. Unmodified — curses and enchantments move the premium, not this, and
263	 * a component block is a premium discount only.
264	 */
265	const insuranceSumOf = (items: Item[]): number =>
266	  items.reduce((total, item) => total + insuranceValueOf(item), 0);
267	
268	const policyFor = (items: Item[]): Policy => ({
269	  items,
270	  remainingCap: toSubunits(insuranceSumOf(items) * CAP_MULTIPLE),
271	});
272	
273	/**
274	 * How much of a damage the MHPCO reimburses, as an exact rational. Unlike a
275	 * `Rate`, a share is the *whole* of what is paid rather than an adjustment to
276	 * it: HALF_REIMBURSEMENT is what the claimant gets, not what they lose, and
277	 * FULL_REIMBURSEMENT is the identity. Shares are multiplied through the
278	 * damage; they are never summed with one another.
279	 */
280	type Share = Fraction;
281	
282	/** The part of `subunits` that `share` reimburses. */
283	const shareAmount = (subunits: number, share: Share): number => partOf(subunits, share);
284	
285	const FULL_REIMBURSEMENT: Share = { num: 100, den: 100 };
286	const HALF_REIMBURSEMENT: Share = { num: 50, den: 100 };
287	
288	/**
289	 * Damage to an item this heavily enchanted is reimbursed at half. Note this is
290	 * a different threshold from HIGH_ENCHANTMENT_LEVEL, which governs the premium.
291	 */
292	const HALF_REIMBURSEMENT_LEVEL = 8;
293	
294	const isHeavilyEnchanted = (item: Item): boolean =>
295	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_LEVEL;
296	
297	/**
298	 * The share of a damage the MHPCO reimburses for an item.
299	 *
300	 * Reimbursement clauses do not stack the way premium modifiers do: exactly one
301	 * clause decides the share, and a share is multiplied through the damage rather
302	 * than summed. This is the opposite of `ratesForItem`, which collects every
303	 * modifier that applies — hence a single answer rather than a list.
304	 *
305	 * The spec also states a dragon-material clause granting *full* reimbursement,
306	 * and it is deliberately absent here. It is unobservable: full reimbursement is
307	 * already the default, and the only reducing clause (half, at enchantment >=
308	 * HALF_REIMBURSEMENT_LEVEL) is specified to win wherever both would apply. So
309	 * the dragon clause can only ever agree with this function, never override it —
310	 * no input exists for which reading `item.material` changes the answer. All
311	 * three worked dragon examples in the spec (enchantment 8 and 9 → half; 5 →
312	 * full) come out right without it.
313	 *
314	 * That makes a dragon branch unfalsifiable code: the suite stays green with it
315	 * above the enchantment check, below it, or gone. It is left out rather than
316	 * written untestable. Should a later clause make material observable — a
317	 * *reducing* dragon rule, or a full-reimbursement clause that outranks the
318	 * half — a failing test will demand it, and this note should go with it.
319	 */
320	const reimbursedShareOf = (item: Item): Share => {
321	  if (isHeavilyEnchanted(item)) return HALF_REIMBURSEMENT;
322	
323	  return FULL_REIMBURSEMENT;
324	};
325	
326	/**
327	 * What the MHPCO reimburses for one damaged item, before the cap is applied:
328	 * the reimbursed share of the damage, less the deductible.
329	 */
330	const reimbursementFor = (damage: Damage, item: Item): number =>
331	  shareAmount(toSubunits(damage.amount), reimbursedShareOf(item)) - toSubunits(DEDUCTIBLE);
332	
333	/** Everything a step may read and advance as the scenario runs. */
334	interface Ledger {
335	  readonly standing: CustomerStanding;
336	  /** Policies by the index of the quote step that created them. */
337	  readonly policies: ReadonlyMap<number, Policy>;
338	}
339	
340	/** The ledger as it stands once `policy` is on record at `stepIndex`. */
341	const withPolicy = (ledger: Ledger, stepIndex: number, policy: Policy): Ledger => ({
342	  ...ledger,
343	  policies: new Map(ledger.policies).set(stepIndex, policy),
344	});
345	
346	/**
347	 * The policy a step names, *assuming* the step names one that exists.
348	 *
349	 * No scenario yet reaches this with a dangling reference, so the assumption
350	 * holds for every case under test. It is stated here rather than asserted
351	 * silently at the call site; the todo tests for claims against absent or
352	 * mismatched policies are what will turn it into a checked failure.
353	 */
354	const assumePolicy = (ledger: Ledger, stepIndex: number): Policy => {
355	  const policy = ledger.policies.get(stepIndex);
356	  if (policy === undefined) throw new Error(`No policy created by step ${stepIndex}`);
357	
358	  return policy;
359	};
360	
361	/**
362	 * Each damage paired with the insured item it befell.
363	 *
364	 * A policy may cover several alike items — two swords, say — and each damage
365	 * entry is a separate item's misfortune. So a matched item is consumed: the
366	 * second sword damage pairs with the *other* sword, which may be enchanted
367	 * differently and so reimbursed differently.
368	 */
369	const damagedItems = (policy: Policy, damages: Damage[]): Item[] => {
370	  const unharmed = [...policy.items];
371	
372	  return damages.map((damage) => {
373	    const found = unharmed.findIndex((covered) => covered.type === damage.itemType);
374	    if (found === -1) throw new Error(`Policy does not cover a ${damage.itemType}`);
375	
376	    return unharmed.splice(found, 1)[0];
377	  });
378	};
379	
380	/** The result of a step, and the ledger as the *next* step will find it. */
381	interface StepOutcome {
382	  readonly result: StepResult;
383	  readonly ledger: Ledger;
384	}
385	
386	/**
387	 * A quote prices the items against the customer's standing, and leaves the
388	 * customer holding one more quote than before — which is what makes the *next*
389	 * quote a follow-up. It also creates the policy that later claims draw on.
390	 */
391	const applyQuote = (step: QuoteStep, ledger: Ledger, stepIndex: number): StepOutcome => ({
392	  result: { premium: quotePremium(step.items, ledger.standing) },
393	  ledger: withPolicy(
394	    { ...ledger, standing: { ...ledger.standing, quotesSoFar: ledger.standing.quotesSoFar + 1 } },
395	    stepIndex,
396	    policyFor(step.items),
397	  ),
398	});
399	
400	/**
401	 * What an incident's damages come to against a policy, before the cap: every
402	 * damaged item reimbursed on its own terms, each less its own deductible.
403	 */
404	const reimbursementForIncident = (incident: Incident, policy: Policy): number => {
405	  const items = damagedItems(policy, incident.damages);
406	
407	  return incident.damages.reduce(
408	    (total, damage, index) => total + reimbursementFor(damage, items[index]),
409	    0,
410	  );
411	};
412	
413	/**
414	 * A claim reimburses each damaged item, less the deductible, and draws the
415	 * total down from the policy's remaining cap.
416	 *
417	 * The cap binds the payout, not merely the report: a claim worth more than the
418	 * policy has left pays out only what remains. Clamping here — in subunits,
419	 * before `toPayoutGold` rounds — is what keeps the cap from running negative
420	 * and lets it reach exactly 0 rather than a rounded near-zero.
421	 */
422	const applyClaim = (step: ClaimStep, ledger: Ledger): StepOutcome => {
423	  const policy = assumePolicy(ledger, step.policy);
424	  const payout = Math.min(
425	    reimbursementForIncident(step.incident, policy),
426	    policy.remainingCap,
427	  );
428	  const remainingCap = policy.remainingCap - payout;
429	
430	  return {
431	    result: { payout: toPayoutGold(payout), remainingCap: toPayoutGold(remainingCap) },
432	    ledger: withPolicy(ledger, step.policy, { ...policy, remainingCap }),
433	  };
434	};
435	
436	/**
437	 * Steps are processed in order, since a step's result can depend on those
438	 * before it — a quote is discounted once the customer holds an earlier one, and
439	 * a claim draws on a policy an earlier quote created.
440	 *
441	 * Each step both produces a result and hands on the ledger the next step will
442	 * see, so that a step's effect on later steps lives with the step's own logic
443	 * rather than in loose accumulators advanced by hand here.
444	 */
445	export const runScenario = (scenario: Scenario): ScenarioResults => {
446	  const results: StepResult[] = [];
447	  let ledger: Ledger = {
448	    standing: { customer: scenario.customer, quotesSoFar: 0 },
449	    policies: new Map(),
450	  };
451	
452	  scenario.steps.forEach((step, stepIndex) => {
453	    const outcome =
454	      step.op === "quote" ? applyQuote(step, ledger, stepIndex) : applyClaim(step, ledger);
455	    results.push(outcome.result);
456	    ledger = outcome.ledger;
457	  });
458	
459	  return { results };
460	};
