4	describe("MHPCO Claim Office", () => {
5	  // --- Quote: base premiums for single main items ---
6	  it("quotes an empty item list at 5 G (processing fee only)", () => {
7	    const result = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    });
11	
12	    expect(result).toEqual({ results: [{ premium: 5 }] });
13	  });
14	  it("quotes a plain sword at 115 G (100 base + 10 first insurance + 5 fee)", () => {
15	    const result = runScenario({
16	      customer: { yearsWithMHPCO: 0 },
17	      steps: [
18	        {
19	          op: "quote",
20	          items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }],
21	        },
22	      ],
23	    });
24	
25	    expect(result).toEqual({ results: [{ premium: 115 }] });
26	  });
27	  it("quotes a plain amulet at 71 G (60 base + 6 first insurance + 5 fee)", () => {
28	    const result = runScenario({
29	      customer: { yearsWithMHPCO: 0 },
30	      steps: [
31	        {
32	          op: "quote",
33	          items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }],
34	        },
35	      ],
36	    });
37	
38	    expect(result).toEqual({ results: [{ premium: 71 }] });
39	  });
40	  it("quotes a plain staff at 93 G (80 base + 8 first insurance + 5 fee)", () => {
