78	    const result = runScenario({
79	      customer: { yearsWithMHPCO: 0 },
80	      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }] }],
81	    });
82	
83	    // 60 base (block) + 6 first insurance + 5 fee
84	    expect(result).toEqual({ results: [{ premium: 71 }] });
85	  });
86	  it("prices 4 runes at 100 G base premium (no block — block requires exactly 3)", () => {
87	    const result = runScenario({
88	      customer: { yearsWithMHPCO: 0 },
89	      steps: [
90	        {
91	          op: "quote",
92	          items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }, { type: "rune" }],
93	        },
94	      ],
95	    });
96	
97	    // 100 base (no block) + 10 first insurance + 5 fee
98	    expect(result).toEqual({ results: [{ premium: 115 }] });
99	  });
100	  it("prices 7 runes at 175 G base premium (no block — block requires exactly 3)", () => {
101	    const result = runScenario({
102	      customer: { yearsWithMHPCO: 0 },
103	      steps: [{ op: "quote", items: Array.from({ length: 7 }, () => ({ type: "rune" })) }],
104	    });
105	
106	    // 175 base + 17.5 first insurance = 192.5, + 5 fee = 197.5, rounded up
107	    expect(result).toEqual({ results: [{ premium: 198 }] });
108	  });
109	
110	  // --- Quote: "alike" means exactly the same component type (❓) ---
111	  it("prices 2 runes + 1 moonstone at 75 G base premium (no block: different types)", () => {
112	    const result = runScenario({
113	      customer: { yearsWithMHPCO: 0 },
114	      steps: [
115	        { op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }] },
116	      ],
117	    });
118	
119	    // 75 base (no block — mixed types) + 7.5 first insurance = 82.5, + 5 fee = 87.5, rounded up
120	    expect(result).toEqual({ results: [{ premium: 88 }] });
121	  });
122	  it("prices 3 runes + 3 moonstones at 120 G base premium (two separate blocks)", () => {
123	    const result = runScenario({
124	      customer: { yearsWithMHPCO: 0 },
125	      steps: [
126	        {
127	          op: "quote",
128	          items: [
129	            { type: "rune" },
130	            { type: "rune" },
131	            { type: "rune" },
132	            { type: "moonstone" },
133	            { type: "moonstone" },
134	            { type: "moonstone" },
135	          ],
136	        },
137	      ],
138	    });
139	
140	    // 60 + 60 base (two blocks) + 12 first insurance = 132, + 5 fee
141	    expect(result).toEqual({ results: [{ premium: 137 }] });
142	  });
143	
